import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Connection pool managed by container
    private Connection getConnection() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
            return ds.getConnection();
        } catch (javax.naming.NamingException e) {
            throw new SQLException("JNDI lookup failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customerId = req.getParameter("cid");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(sales|inventory|returns)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Customer ID validated as numeric
        if (customerId == null || !customerId.matches("\\d+")) {
            resp.sendError(400, "Invalid customer ID");
            return;
        }

        // Sort column - allow flexibility for dynamic reporting
        if (sortCol == null) {
            sortCol = "created_at";
        }

        String[] dates = dateRange.split("_");

        // Build query - parameterized for values, dynamic for sort
        String query = "SELECT id, customer_id, amount, status, created_at FROM " 
            + reportType + "_reports "
            + "WHERE customer_id = ? AND created_at BETWEEN ? AND ? "
            + "ORDER BY " + sortCol + " DESC LIMIT 500";

        log.info("Report query for customer " + customerId + ": type=" + reportType);

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(query)) {

            ps.setInt(1, Integer.parseInt(customerId));
            ps.setString(2, dates[0]);
            ps.setString(3, dates[1]);

            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"cid\":%d,\"amount\":\"%.2f\",\"status\":\"%s\",\"date\":\"%s\"}",
                    rs.getInt("id"), rs.getInt("customer_id"),
                    rs.getDouble("amount"), rs.getString("status"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("]}");

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
